-- SQL DDL for ClickHouse, generated by ormbridge.

CREATE TABLE category (
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  id UUID DEFAULT generateUUIDv4(),
  name String,
  slug String,
  parent_id Nullable(UUID)
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE post (
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  id UUID DEFAULT generateUUIDv4(),
  public_id UUID DEFAULT generateUUIDv4(),
  title String,
  body String,
  status Enum8('draft' = 1, 'published' = 2) DEFAULT 'draft',
  rating Nullable(Decimal(4, 2)),
  view_count Int32 DEFAULT 0,
  is_featured Bool DEFAULT false,
  published_at DateTime64(3) DEFAULT now64(3),
  metadata String DEFAULT '{}' COMMENT 'JSON document',
  author_id UUID,
  editor_id Nullable(UUID),
  category_id UUID,
  INDEX post_title_idx title TYPE bloom_filter GRANULARITY 1,
  INDEX uniq_post_author_title (author_id, title) TYPE set(100) GRANULARITY 4,
  INDEX post_pub_status_idx (published_at, status) TYPE set(100) GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE tag (
  id UUID DEFAULT generateUUIDv4(),
  label String,
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3)
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE profile (
  id UUID DEFAULT generateUUIDv4(),
  bio Nullable(String),
  avatar Nullable(String),
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  user_id UUID
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE `user` (
  id UUID DEFAULT generateUUIDv4(),
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3)
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE post_tag (
  id UUID DEFAULT generateUUIDv4(),
  post_id UUID,
  tag_id UUID,
  INDEX post_tag_post_id_tag_id_idx (post_id, tag_id) TYPE set(100) GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id)
COMMENT 'many-to-many join table';
